1	/* NeuroSpect v2 — Remaining Pages: Features, Performance, Architecture, Compare, Pricing */
2	
3	/* ═══ UPCOMING FEATURES (EdgeLab Research Studio) ═══ */
4	function FeaturesPage() {
5	  var engState = React.useState(null);
6	  var engine = engState[0], setEngine = engState[1];
7	  var wfState = React.useState({ running: false, idx: -1 });
8	  var wfAnim = wfState[0], setWfAnim = wfState[1];
9	
10	  function runWf() {
11	    setWfAnim({ running: true, idx: 0 });
12	    var i = 0;
13	    var iv = setInterval(function() { i++; if (i >= AEE_WORKFLOW_STEPS.length) { clearInterval(iv); setTimeout(function() { setWfAnim({ running: false, idx: -1 }); }, 1500); } else { setWfAnim({ running: true, idx: i }); } }, 700);
14	  }
15	
16	  return (
17	    <div className="page">
18	      <Rv>
19	        <div className="hero-grad" style={{ padding: 'clamp(2rem,4vw,3rem)', marginBottom: '1.5rem' }}>
20	          <span className="badge badge-blue" style={{ marginBottom: 14 }}><span className="badge-dot" style={{ background: '#8b5cf6' }}></span>Phase 8</span>
21	          <h1 style={{ marginBottom: 10 }}><span className="grad-text">EdgeLab Research Studio</span></h1>
22	          <p style={{ fontSize: '0.92rem', color: 'var(--text-m)', maxWidth: 520, lineHeight: 1.65, marginBottom: 20 }}>
23	            Every win, loss, and regime shift converted into validated edge. Three engines powering one continuous improvement loop.
24	          </p>
25	        </div>
26	      </Rv>
27	
28	      {/* Core Engines */}
29	      <Rv delay={60}>
30	        <h2 style={{ fontSize: '1.1rem', marginBottom: 14 }}>Core Engines</h2>
31	        <div className="bento bento-3" style={{ marginBottom: '1.5rem' }}>
32	          {AEE_CORE_ENGINES.map(function(eng, i) {
33	            var isOpen = engine === eng.id;
34	            return (
35	              <Rv key={eng.id} delay={i * 50}>
36	                <div className={'card ' + (isOpen ? 'card-active' : '')} style={{ cursor: 'pointer', height: '100%', display: 'flex', flexDirection: 'column', borderLeftWidth: 3, borderLeftColor: eng.color }}
37	                  onClick={function() { setEngine(isOpen ? null : eng.id); }}>
38	                  <h3 style={{ fontSize: '0.9rem', marginBottom: 4 }}>{eng.name}</h3>
39	                  <p className="mono" style={{ fontSize: '0.72rem', color: eng.color, fontStyle: 'italic', marginBottom: 8 }}>"{eng.tagline}"</p>
40	                  <p style={{ fontSize: '0.78rem', color: 'var(--text-m)', lineHeight: 1.5, flex: 1, marginBottom: 8 }}>{eng.desc}</p>
41	                  <div style={{ maxHeight: isOpen ? 500 : 0, overflow: 'hidden', transition: 'max-height 0.5s cubic-bezier(0.16,1,0.3,1)' }}>
42	                    <div style={{ height: 1, background: eng.color + '33', marginBottom: 10 }}></div>
43	                    {eng.capabilities.map(function(cap, ci) {
44	                      return <div key={ci} style={{ marginBottom: 6, paddingLeft: 10, borderLeft: '2px solid ' + eng.color + '33' }}>
45	                        <p style={{ fontSize: '0.78rem', fontWeight: 600, color: 'var(--text-h)', marginBottom: 1 }}>{cap.name}</p>
46	                        <p style={{ fontSize: '0.72rem', color: 'var(--text-m)' }}>{cap.desc}</p>
47	                      </div>;
48	                    })}
49	                  </div>
50	                  <span style={{ fontSize: '0.65rem', color: 'var(--text-d)', textAlign: 'center', marginTop: 4 }}>{isOpen ? '▲ Collapse' : '▼ View capabilities'}</span>
51	                </div>
52	              </Rv>
53	            );
54	          })}
55	        </div>
56	      </Rv>
57	
58	      {/* E2E Workflow */}
59	      <Rv delay={100}>
60	        <h2 style={{ fontSize: '1.1rem', marginBottom: 14 }}>End-to-End: Losing Trade → <span className="grad-text">Validated Edge</span></h2>
61	        <div className="card card-active" style={{ marginBottom: '1.5rem', padding: 'clamp(1rem,2.5vw,1.5rem)' }}>
62	          <div style={{ display: 'flex', flexDirection: 'column', gap: 0, marginBottom: 16 }}>
63	            {AEE_WORKFLOW_STEPS.map(function(step, i) {
64	              var isActive = wfAnim.idx === i, isPast = wfAnim.idx > i;
65	              return (
66	                <div key={i} style={{ display: 'flex', gap: 12, alignItems: 'flex-start', position: 'relative', opacity: wfAnim.running && wfAnim.idx < i ? 0.2 : 1, transition: 'opacity 0.4s' }}>
67	                  {i < AEE_WORKFLOW_STEPS.length - 1 && <div style={{ position: 'absolute', left: 15, top: 34, width: 2, height: 'calc(100% - 12px)', background: isPast ? step.color + '44' : 'rgba(59,130,246,0.06)' }}></div>}
68	                  <div style={{ width: 32, height: 32, borderRadius: 8, flexShrink: 0, border: '1.5px solid ' + (isActive ? step.color : 'rgba(59,130,246,0.08)'), background: isActive ? step.color + '18' : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--font-m)', fontSize: '0.6rem', color: isActive ? step.color : 'var(--text-d)', zIndex: 2, boxShadow: isActive ? '0 0 14px ' + step.color + '25' : 'none', transition: 'all 0.3s' }}>{step.num}</div>
69	                  <div style={{ flex: 1, paddingBottom: 12 }}>
70	                    <p style={{ fontSize: '0.82rem', fontWeight: 600, color: isActive ? 'var(--text-h)' : 'var(--text-b)', marginBottom: 2 }}>{step.title}</p>
71	                    <p style={{ fontSize: '0.72rem', color: 'var(--text-m)', lineHeight: 1.5 }}>{step.desc}</p>
72	                  </div>
73	                </div>
74	              );
75	            })}
76	          </div>
77	          <div style={{ textAlign: 'center' }}>
78	            <button onClick={runWf} disabled={wfAnim.running} className="btn btn-blue btn-sm" style={{ opacity: wfAnim.running ? 0.5 : 1 }}>
79	              {wfAnim.running ? 'Processing...' : '▶ Run Workflow'}
80	            </button>
81	          </div>
82	        </div>
83	      </Rv>
84	
85	      {/* Roadmap */}
86	      <Rv delay={140}>
87	        <h2 style={{ fontSize: '1.1rem', marginBottom: 14 }}>Roadmap</h2>
88	        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
89	          {AEE_ROADMAP.map(function(phase, i) {
90	            var isCurrent = phase.phase === 8;
91	            return (
92	              <Rv key={i} delay={i * 50}>
93	                <div className={'card ' + (isCurrent ? 'card-active' : '')} style={{ borderLeftWidth: 3, borderLeftColor: isCurrent ? 'var(--blue-500)' : 'rgba(59,130,246,0.08)' }}>
94	                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
95	                    <span className="mono" style={{ fontSize: '0.75rem', fontWeight: 700, color: isCurrent ? 'var(--blue-400)' : 'var(--text-d)' }}>Phase {phase.phase}</span>
96	                    <h3 style={{ fontSize: '0.9rem' }}>{phase.title}</h3>
97	                    {isCurrent && <span className="badge badge-blue" style={{ fontSize: '0.55rem' }}>Current</span>}
98	                  </div>
99	                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
100	                    {phase.items.map(function(item) {
101	                      return <span key={item} style={{ fontSize: '0.7rem', padding: '3px 8px', borderRadius: 5, background: 'rgba(59,130,246,0.04)', border: '1px solid rgba(59,130,246,0.08)', color: 'var(--text-m)' }}>{item}</span>;
102	                    })}
103	                  </div>
104	                </div>
105	              </Rv>
106	            );
107	          })}
108	        </div>
109	      </Rv>
110	    </div>
111	  );
112	}
113	
114	/* ═══ PERFORMANCE ═══ */
115	function PerformancePage() {
116	  var tierState = React.useState('all');
117	  var activeTier = tierState[0], setActiveTier = tierState[1];
118	
119	  var W = 600, H = 200, P = { t: 12, r: 12, b: 20, l: 48 };
120	  var allV = []; TIER_ORDER.forEach(function(id) { EQUITY_RAW[id].forEach(function(v) { allV.push(v); }); });
121	  var mn = Math.min.apply(null, allV) - 500, mx = Math.max.apply(null, allV) + 500;
122	  var xS = (W - P.l - P.r) / (EQUITY_RAW.tier1.length - 1);
123	  var yS = function(v) { return P.t + (1 - (v - mn) / (mx - mn)) * (H - P.t - P.b); };
124	
125	  return (
126	    <div className="page">
127	      <Rv>
128	        <div className="hero-grad" style={{ padding: 'clamp(2rem,4vw,3rem)', marginBottom: '1.5rem' }}>
129	          <span className="badge badge-gold" style={{ marginBottom: 14 }}>Illustrative Demo Data</span>
130	          <h1 style={{ marginBottom: 10 }}>Structure Changes <span className="grad-text">Performance</span></h1>
131	          <p style={{ fontSize: '0.92rem', color: 'var(--text-m)', maxWidth: 520, lineHeight: 1.65 }}>One-month NQ performance lab comparing four trader workflows.</p>
132	        </div>
133	      </Rv>
134	      <Rv delay={60}>
135	        <div className="card card-active" style={{ marginBottom: '1.5rem', padding: '1rem' }}>
136	          <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 12 }}>
137	            {TIER_ORDER.map(function(id) {
138	              var t = TIER_META[id];
139	              return <button key={id} onClick={function() { setActiveTier(activeTier === id ? 'all' : id); }}
140	                style={{ display: 'flex', alignItems: 'center', gap: 5, padding: '5px 10px', borderRadius: 6, border: '1px solid rgba(59,130,246,0.08)', background: activeTier === id ? t.color + '22' : 'transparent', fontSize: '0.75rem', color: 'var(--text-b)', opacity: activeTier !== 'all' && activeTier !== id ? 0.3 : 1, transition: 'all 0.2s' }}>
141	                <span style={{ width: 7, height: 7, borderRadius: '50%', background: t.color }}></span>{t.short}
142	              </button>;
143	            })}
144	          </div>
145	          <svg viewBox={'0 0 ' + W + ' ' + H} style={{ width: '100%', display: 'block' }}>
146	            {[22000,24000,26000,28000,30000,32000,34000].filter(function(v) { return v >= mn && v <= mx; }).map(function(v) {
147	              return React.createElement('g', { key: v },
148	                React.createElement('line', { x1: P.l, y1: yS(v), x2: W - P.r, y2: yS(v), stroke: 'rgba(59,130,246,0.06)', strokeWidth: 1 }),
149	                React.createElement('text', { x: P.l - 4, y: yS(v) + 3, textAnchor: 'end', fill: 'rgba(255,255,255,0.2)', fontSize: 8, fontFamily: 'var(--font-m)' }, '$' + (v / 1000).toFixed(0) + 'k'));
150	            })}
151	            {TIER_ORDER.map(function(id) {
152	              var d = EQUITY_RAW[id];
153	              var path = d.map(function(v, i) { return (i === 0 ? 'M' : 'L') + (P.l + i * xS) + ',' + yS(v); }).join(' ');
154	              var show = activeTier === 'all' || activeTier === id;
155	              return React.createElement('path', { key: id, d: path, fill: 'none', stroke: TIER_META[id].color, strokeWidth: activeTier === id ? 2.5 : 1.5, opacity: show ? 1 : 0.08, style: { transition: 'opacity 0.3s' } });
156	            })}
157	          </svg>
158	        </div>
159	      </Rv>
160	      <Rv delay={100}>
161	        <div className="bento bento-4">
162	          {TIER_ORDER.map(function(id) {
163	            var t = TIER_META[id], k = TIER_KPIS[id];
164	            return <div key={id} className="card" style={{ borderLeftWidth: 3, borderLeftColor: t.color }}>
165	              <h3 style={{ fontSize: '0.85rem', marginBottom: 8 }}>{t.short}</h3>
166	              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 }}>
167	                {[['WR', (k.winRate * 100).toFixed(0) + '%'], ['PF', k.profitFactor], ['DD', '-$' + k.maxDrawdown.toLocaleString()], ['Net', (k.netPnl >= 0 ? '+$' : '-$') + Math.abs(k.netPnl).toLocaleString()]].map(function(p) {
168	                  return <div key={p[0]}><span className="label">{p[0]}</span><div className="mono" style={{ fontSize: '0.9rem', color: String(p[1]).charAt(0) === '-' ? '#ef4444' : String(p[1]).charAt(0) === '+' ? '#10b981' : 'var(--blue-400)' }}>{p[1]}</div></div>;
169	                })}
170	              </div>
171	            </div>;
172	          })}
173	        </div>
174	      </Rv>
175	    </div>
176	  );
177	}
178	
179	/* ═══ ARCHITECTURE ═══ */
180	function ArchitecturePage() {
181	  return (
182	    <div className="page">
183	      <Rv>
184	        <div className="hero-grad" style={{ padding: 'clamp(2rem,4vw,3rem)', marginBottom: '1.5rem' }}>
185	          <h1 style={{ marginBottom: 10 }}>Six Components. <span className="grad-text">One Platform.</span></h1>
186	          <p style={{ fontSize: '0.92rem', color: 'var(--text-m)', maxWidth: 520, lineHeight: 1.65 }}>Every component is purpose-built for ICT trading. They connect, feed each other, and compound your edge.</p>
187	        </div>
188	      </Rv>
189	      <Rv delay={60}>
190	        <div className="bento bento-3" style={{ marginBottom: '1.5rem' }}>
191	          {COMPONENTS.map(function(c, i) {
192	            return <Rv key={c.id} delay={i * 40}>
193	              <div className="card" style={{ height: '100%', borderLeftWidth: 3, borderLeftColor: c.color }}>
194	                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
195	                  <span style={{ width: 8, height: 8, borderRadius: '50%', background: c.color, boxShadow: '0 0 8px ' + c.color + '50' }}></span>
196	                  <h3 style={{ fontSize: '0.9rem' }}>{c.name}</h3>
197	                </div>
198	                <span className="label" style={{ color: c.color, display: 'block', marginBottom: 6 }}>{c.sub}</span>
199	                <p style={{ fontSize: '0.78rem', color: 'var(--text-m)', lineHeight: 1.5, marginBottom: 8 }}>{c.desc}</p>
200	                <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
201	                  {c.features.map(function(f) { return <div key={f} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: '0.72rem' }}><span style={{ color: c.color, fontSize: '0.5rem' }}>●</span><span style={{ color: 'var(--text-b)' }}>{f}</span></div>; })}
202	                </div>
203	              </div>
204	            </Rv>;
205	          })}
206	        </div>
207	      </Rv>
208	      <Rv delay={100}>
209	        <div className="card" style={{ padding: '1.25rem' }}>
210	          <h3 style={{ marginBottom: 14 }}>Data Flow</h3>
211	          <div className="bento bento-4">
212	            {[{n:'01',t:'Ingest',d:'ICT content + journal → NeuroCore index'},{n:'02',t:'Retrieve & Reason',d:'NeuroCore retrieves → NSLM generates with citations'},{n:'03',t:'Research & Validate',d:'EdgeLab backtests → promotes validated models'},{n:'04',t:'Execute',d:'NeuroTrader uses NeuroQuant with 5 safety layers'}].map(function(d) {
213	              return <div key={d.n}><span style={{ fontSize: '1.5rem', fontWeight: 800, color: 'rgba(59,130,246,0.12)', fontFamily: 'var(--font-h)' }}>{d.n}</span><h3 style={{ fontSize: '0.85rem', marginBottom: 3 }}>{d.t}</h3><p style={{ fontSize: '0.72rem', color: 'var(--text-m)' }}>{d.d}</p></div>;
214	            })}
215	          </div>
216	        </div>
217	      </Rv>
218	    </div>
219	  );
220	}
221	
222	/* ═══ COMPARE ═══ */
223	function ComparePage() {
224	  return (
225	    <div className="page">
226	      <Rv>
227	        <div className="hero-grad" style={{ padding: 'clamp(2rem,4vw,3rem)', marginBottom: '1.5rem' }}>
228	          <h1 style={{ marginBottom: 10 }}>Stop Duct-Taping Your <span className="grad-text">Workflow</span></h1>
229	          <p style={{ fontSize: '0.92rem', color: 'var(--text-m)', maxWidth: 520, lineHeight: 1.65 }}>Most ICT traders juggle 5–8 disconnected tools. NeuroSpect replaces the patchwork.</p>
230	        </div>
231	      </Rv>
232	      <Rv delay={60}>
233	        <div className="bento bento-2" style={{ marginBottom: '1.5rem' }}>
234	          <div className="card" style={{ borderLeftWidth: 3, borderLeftColor: '#ef4444' }}>
235	            <h3 style={{ fontSize: '0.9rem', marginBottom: 10, display: 'flex', alignItems: 'center', gap: 6 }}><span style={{ color: '#ef4444' }}>✗</span> Before NeuroSpect</h3>
236	            <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
237	              {BEFORE_TOOLS.map(function(t) {
238	                return <div key={t.name} style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 10px', borderRadius: 6, background: 'rgba(239,68,68,0.03)', border: '1px solid rgba(239,68,68,0.06)' }}>
239	                  <span style={{ fontSize: '0.78rem', color: 'var(--text-b)' }}>{t.name}</span>
240	                  <span className="mono" style={{ fontSize: '0.72rem', color: '#ef4444' }}>{t.cost}</span>
241	                </div>;
242	              })}
243	            </div>
244	            <div style={{ marginTop: 8, padding: '8px', borderRadius: 6, background: 'rgba(239,68,68,0.06)', textAlign: 'center' }}>
245	              <span className="mono" style={{ fontSize: '1rem', fontWeight: 700, color: '#ef4444' }}>$125–$710/mo</span>
246	            </div>
247	          </div>
248	          <div className="card card-active" style={{ borderLeftWidth: 3, borderLeftColor: 'var(--blue-500)' }}>
249	            <h3 style={{ fontSize: '0.9rem', marginBottom: 10, display: 'flex', alignItems: 'center', gap: 6 }}><span style={{ color: '#10b981' }}>✓</span> With NeuroSpect</h3>
250	            <p style={{ fontSize: '0.82rem', color: 'var(--text-m)', marginBottom: 12 }}>One platform. Every tool. Shared context across coaching, journal, backtesting, and research.</p>
251	            {['AI coaching with citations','100+ field trade journal','Event-driven backtesting','Risk limit engine','Strategy research (EdgeLab)','Automated trading agent'].map(function(f) {
252	              return <div key={f} style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4, fontSize: '0.78rem' }}><span style={{ color: '#10b981' }}>✓</span><span style={{ color: 'var(--text-b)' }}>{f}</span></div>;
253	            })}
254	            <div style={{ marginTop: 10, padding: '8px', borderRadius: 6, background: 'rgba(59,130,246,0.06)', textAlign: 'center' }}>
255	              <span className="mono" style={{ fontSize: '1rem', fontWeight: 700, color: 'var(--blue-400)' }}>$29–$349/mo</span>
256	            </div>
257	          </div>
258	        </div>
259	      </Rv>
260	    </div>
261	  );
262	}
263	
264	/* ═══ PRICING ═══ */
265	function PricingPage() {
266	  return (
267	    <div className="page">
268	      <Rv>
269	        <div className="hero-grad" style={{ padding: 'clamp(2rem,4vw,3rem)', marginBottom: '1.5rem' }}>
270	          <h1 style={{ marginBottom: 10 }}>Grow Into Your <span className="grad-text">Edge</span></h1>
271	          <p style={{ fontSize: '0.92rem', color: 'var(--text-m)', maxWidth: 520, lineHeight: 1.65 }}>Start free. Upgrade as your trading evolves.</p>
272	        </div>
273	      </Rv>
274	      <Rv delay={60}>
275	        <div className="bento bento-3">
276	          {PRICING_TIERS.map(function(t, i) {
277	            return (
278	              <Rv key={t.name} delay={i * 40}>
279	                <div className={'card ' + (t.highlight ? 'card-active' : '')} style={{ height: '100%', display: 'flex', flexDirection: 'column', position: 'relative' }}>
280	                  {t.highlight && <div style={{ position: 'absolute', top: -10, left: '50%', transform: 'translateX(-50%)' }}><span className="badge badge-blue" style={{ fontSize: '0.55rem', background: 'var(--blue-500)', color: '#fff', border: 'none', fontWeight: 700 }}>Most Popular</span></div>}
281	                  <h3 style={{ fontSize: '1rem', marginBottom: 2 }}>{t.name}</h3>
282	                  <p style={{ fontSize: '0.7rem', color: 'var(--text-d)', marginBottom: 12 }}>{t.target}</p>
283	                  <div style={{ display: 'flex', alignItems: 'baseline', gap: 3, marginBottom: 14 }}>
284	                    <span style={{ fontSize: '2rem', fontWeight: 800, color: 'var(--text-h)', fontFamily: 'var(--font-h)' }}>${t.price}</span>
285	                    <span style={{ fontSize: '0.78rem', color: 'var(--text-d)' }}>{t.period}</span>
286	                  </div>
287	                  <button className={'btn btn-sm ' + (t.highlight ? 'btn-blue' : 'btn-ghost')} style={{ width: '100%', marginBottom: 14 }}>
288	                    {t.price === '0' ? 'Get Started' : 'Join Waitlist'}
289	                  </button>
290	                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6, flex: 1 }}>
291	                    {t.features.map(function(f) {
292	                      return <div key={f} style={{ display: 'flex', alignItems: 'flex-start', gap: 6, fontSize: '0.75rem' }}>
293	                        <span style={{ color: t.highlight ? 'var(--blue-400)' : 'var(--text-d)', flexShrink: 0, marginTop: 1 }}>✓</span>
294	                        <span style={{ color: 'var(--text-m)' }}>{f}</span>
295	                      </div>;
296	                    })}
297	                  </div>
298	                </div>
299	              </Rv>
300	            );
301	          })}
302	        </div>
303	      </Rv>
304	      <Rv delay={200}>
305	        <div className="card card-gold" style={{ textAlign: 'center', padding: '1.5rem', marginTop: '1.5rem' }}>
306	          <p style={{ fontSize: '0.75rem', color: 'var(--text-d)' }}>NeuroSpect is an educational tool. Not financial advice. Past performance does not guarantee future results. Trading involves risk of loss.</p>
307	        </div>
308	      </Rv>
309	    </div>
310	  );
311	}
312	
313	window.FeaturesPage = FeaturesPage;
314	window.PerformancePage = PerformancePage;
315	window.ArchitecturePage = ArchitecturePage;
316	window.ComparePage = ComparePage;
317	window.PricingPage = PricingPage;
