class TestMarketingSitePages:
    """v2 app must expose all 8 routes declared in the HTML shell."""

    def _v2_html(self) -> str:
        return (ROOT / "neurospect-ui" / "NeuroSpect v2.html").read_text(encoding="utf-8")

    def test_html_file_exists(self):
        assert (ROOT / "neurospect-ui" / "NeuroSpect v2.html").exists()

    def test_all_routes_present_in_shell(self):
        html = self._v2_html()
        expected_routes = ["home", "course", "backtesting", "performance",
                           "architecture", "features", "compare", "pricing"]
        for route in expected_routes:
            assert route in html, f"Route '{route}' missing from v2 shell"

    def test_six_or_more_pages(self):
        html = self._v2_html()
        # Pages dict uses identifier keys: `home: HomePage` (no quotes)
        routes = re.findall(r"(\w+):\s*\w+Page", html)
        # Filter to known route names only (exclude React variable names etc.)
        known = {"home", "course", "backtesting", "performance",
                 "architecture", "features", "compare", "pricing"}
        found = [r for r in routes if r in known]
        assert len(found) >= 6, f"Expected ≥6 page routes, found {len(found)}: {found}"

    def test_required_jsx_source_files_exist(self):
        ui = ROOT / "neurospect-ui"
        for fname in ["v2/v2-shell.jsx", "v2/v2-home-course.jsx",
                      "v2/v2-pages.jsx", "v2/v2-backtesting.jsx"]:
            assert (ui / fname).exists(), f"Missing: {fname}"

    def test_data_files_exist(self):
        ui = ROOT / "neurospect-ui"
        for fname in ["ns-data.js", "ns-course-data.js", "ns-features-data.js"]:
            assert (ui / fname).exists(), f"Missing data file: {fname}"

    def test_waitlist_cta_present(self):
        """Pricing / sidebar must include a 'Join Waitlist' CTA."""
        html = self._v2_html()
        assert "Join Waitlist" in html or "waitlist" in html.lower()

    def test_disclaimer_present(self):
        """Marketing copy must include financial disclaimer."""
        html = self._v2_html()
        disclaimer_keywords = ["not financial advice", "trading involves risk",
                                "educational tool"]
        text = html.lower()
        assert any(kw in text for kw in disclaimer_keywords), \
            "Financial disclaimer missing from marketing site"


